-- Generated by Ingestron from transforms/customers_clean.yaml (table customers_clean). Do not edit: change the definitions and generate again.
CREATE OR REFRESH MATERIALIZED VIEW `silver`.`customers_clean` (
  CONSTRAINT `id_not_null` EXPECT (`id` IS NOT NULL) ON VIOLATION DROP ROW,
  CONSTRAINT `email_not_null` EXPECT (`email` IS NOT NULL) ON VIOLATION DROP ROW,
  CONSTRAINT `updated_at_not_null` EXPECT (`updated_at` IS NOT NULL) ON VIOLATION DROP ROW,
  CONSTRAINT `email_min_length` EXPECT (`email` IS NULL OR length(`email`) >= 3),
  CONSTRAINT `email_pattern` EXPECT (`email` IS NULL OR `email` RLIKE '^[^@]+@[^@]+$'),
  CONSTRAINT `name_max_length` EXPECT (`name` IS NULL OR length(`name`) <= 100),
  CONSTRAINT `country_invalidvalues` EXPECT (`country` IS NULL OR `country` IN ('GB', 'IE', 'FR')),
  CONSTRAINT `status_missingvalues` EXPECT (`status` IS NOT NULL AND `status` NOT IN ('n/a')),
  CONSTRAINT `segment_missingvalues` EXPECT (`segment` IS NULL OR `segment` NOT IN ('unknown')),
  CONSTRAINT `phone_nullvalues` EXPECT (`phone` IS NOT NULL),
  CONSTRAINT `code_invalidvalues` EXPECT (`code` IS NULL OR `code` RLIKE '^[A-Z]{3}$'),
  CONSTRAINT `age_minimum` EXPECT (`age` IS NULL OR `age` >= 0),
  CONSTRAINT `age_exclusive_maximum` EXPECT (`age` IS NULL OR `age` < 150),
  CONSTRAINT `score_multiple_of` EXPECT (`score` IS NULL OR `score` % 5 = 0),
  CONSTRAINT `tags_min_items` EXPECT (`tags` IS NULL OR size(`tags`) >= 1),
  CONSTRAINT `tags_max_items` EXPECT (`tags` IS NULL OR size(`tags`) <= 5),
  CONSTRAINT `tags_unique_items` EXPECT (`tags` IS NULL OR size(array_distinct(`tags`)) = size(`tags`)),
  CONSTRAINT `recent` EXPECT (updated_at >= TIMESTAMP '2000-01-01') ON VIOLATION FAIL UPDATE
)
COMMENT 'CRM customers.'
CLUSTER BY AUTO
AS
SELECT *
FROM (
SELECT `id`, lower(nullif(trim(`email`), '')) AS `email`, nullif(`name`, '') AS `name`, upper(CASE nullif(trim(`country`), '') WHEN 'United Kingdom' THEN 'GB' WHEN 'UK' THEN 'GB' WHEN '-' THEN NULL ELSE nullif(trim(`country`), '') END) AS `country`, coalesce(nullif(trim(`status`), ''), 'active') AS `status`, nullif(trim(`segment`), '') AS `segment`, nullif(trim(`phone`), '') AS `phone`, nullif(trim(`code`), '') AS `code`, `age`, CASE `score` WHEN -1 THEN 0 ELSE `score` END AS `score`, `tags`, coalesce(`vip`, FALSE) AS `vip`, to_utc_timestamp(`signed_up`, 'Europe/London') AS `signed_up`, from_utc_timestamp(to_utc_timestamp(`contacted_at`, 'UTC'), 'Europe/London') AS `contacted_at`, convert_timezone('Europe/London', 'UTC', `last_seen`) AS `last_seen`, to_utc_timestamp(`updated_at`, 'Europe/London') AS `updated_at`, * EXCEPT (`id`, `email`, `name`, `country`, `status`, `segment`, `phone`, `code`, `age`, `score`, `tags`, `vip`, `signed_up`, `contacted_at`, `last_seen`, `updated_at`)
FROM (
SELECT * FROM `bronze`.`customers`
) AS source
) AS cleansed
QUALIFY row_number() OVER (PARTITION BY `id` ORDER BY `updated_at` DESC) = 1;

-- Rows that a check with the action drop removed from customers_clean, with the checks they failed.
CREATE OR REFRESH MATERIALIZED VIEW `silver`.`customers_clean_quarantine`
COMMENT 'Rows of customers_clean that failed a check that drops rows; _failed_checks names the checks.'
AS SELECT *, filter(array(IF(`id` IS NOT NULL, NULL, 'id_not_null'), IF(`email` IS NOT NULL, NULL, 'email_not_null'), IF(`updated_at` IS NOT NULL, NULL, 'updated_at_not_null')), name -> name IS NOT NULL) AS _failed_checks
FROM (
SELECT *
FROM (
SELECT `id`, lower(nullif(trim(`email`), '')) AS `email`, nullif(`name`, '') AS `name`, upper(CASE nullif(trim(`country`), '') WHEN 'United Kingdom' THEN 'GB' WHEN 'UK' THEN 'GB' WHEN '-' THEN NULL ELSE nullif(trim(`country`), '') END) AS `country`, coalesce(nullif(trim(`status`), ''), 'active') AS `status`, nullif(trim(`segment`), '') AS `segment`, nullif(trim(`phone`), '') AS `phone`, nullif(trim(`code`), '') AS `code`, `age`, CASE `score` WHEN -1 THEN 0 ELSE `score` END AS `score`, `tags`, coalesce(`vip`, FALSE) AS `vip`, to_utc_timestamp(`signed_up`, 'Europe/London') AS `signed_up`, from_utc_timestamp(to_utc_timestamp(`contacted_at`, 'UTC'), 'Europe/London') AS `contacted_at`, convert_timezone('Europe/London', 'UTC', `last_seen`) AS `last_seen`, to_utc_timestamp(`updated_at`, 'Europe/London') AS `updated_at`, * EXCEPT (`id`, `email`, `name`, `country`, `status`, `segment`, `phone`, `code`, `age`, `score`, `tags`, `vip`, `signed_up`, `contacted_at`, `last_seen`, `updated_at`)
FROM (
SELECT * FROM `bronze`.`customers`
) AS source
) AS cleansed
QUALIFY row_number() OVER (PARTITION BY `id` ORDER BY `updated_at` DESC) = 1
) AS checked
WHERE NOT coalesce((`id` IS NOT NULL) AND (`email` IS NOT NULL) AND (`updated_at` IS NOT NULL), FALSE);
